"use client"

import React, { useRef, useState, useEffect, forwardRef } from 'react';
import { Circle, Pause, Play } from 'lucide-react';
import ParticleAnimation, { ParticleAnimationHandle } from './particleAnimation';
import { Button } from '@/components/ui/button';

/**
 * AudioInteraction component.
 * Audio interaction component for AI voice interactions with particle animation and timer.
 * ++++++++++++++++
 * Props:
 * @prop onAudioStart - Callback function called when audio starts.
 * @prop onAudioStop - Callback function called when audio stops.
 * @prop onAudioPause - Callback function called when audio pauses.
 * @prop onAudioResume - Callback function called when audio resumes.
 */
type AudioInteractionProps = {
  onAudioStart?: () => void;
  onAudioStop?: () => void;
  onAudioPause?: () => void;
  onAudioResume?: () => void;
};

type Status = 'idle' | 'playing' | 'paused';

const AudioInteraction = forwardRef<HTMLDivElement, AudioInteractionProps>(({
  onAudioStart,
  onAudioStop,
  onAudioPause,
  onAudioResume,
  ...props
}, ref) => {
  const RefParticularAnimation = useRef<ParticleAnimationHandle>(null);
  const [status, setStatus] = useState<Status>('idle');
  const [timeElapsed, setTimeElapsed] = useState(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Gestion du timer pour le temps d'animation
  useEffect(() => {
    if (status === 'playing') {
      timerRef.current = setInterval(() => {
        setTimeElapsed((prev) => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current !== null) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }

    return () => {
      if (timerRef.current !== null) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [status]);

  // Formater le temps en MM:SS
  const formatTime = (seconds: number): string => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
  };

  const handleStart = () => {
    if (RefParticularAnimation.current) {
      RefParticularAnimation.current.startAnimation();
      setStatus('playing');
      setTimeElapsed(0);
      onAudioStart?.();
    }
  };

  const handlePause = () => {
    if (RefParticularAnimation.current) {
      RefParticularAnimation.current.pauseAnimation();
      setStatus('paused');
      onAudioPause?.();
    }
  };

  const handleResume = () => {
    if (RefParticularAnimation.current) {
      // Use resumeAnimation to continue particles on their current trajectories
      RefParticularAnimation.current.resumeAnimation();
      setStatus('playing');
      onAudioResume?.();
    }
  };

  const handleStop = () => {
    if (RefParticularAnimation.current) {
      RefParticularAnimation.current.stopAnimation();
      setStatus('idle');
      setTimeElapsed(0);
      onAudioStop?.();
    }
  };

  return (  
    <div ref={ref} className="flex flex-col justify-center items-center gap-4 p-4" {...props}>
      <ParticleAnimation ref={RefParticularAnimation} />
      <div className="flex gap-2 justify-center items-center gap-x-4">
        {status === 'idle' && (
          <Button onClick={handleStart} variant="default">
            <Play className="mr-2 h-4 w-4" /> Start
          </Button>
        )}
        {status === 'playing' && (
          <Button onClick={handlePause} variant="default">
            <Pause className="mr-2 h-4 w-4" /> Pause
          </Button>
        )}
        {status === 'paused' && (
          <Button onClick={handleResume} variant="default">
            <Play className="mr-2 h-4 w-4" /> Resume
          </Button>
        )}
        <div className="text-lg font-mono">{formatTime(timeElapsed)}</div>
        <Button onClick={handleStop} variant="default">
          <Circle className="mr-2 h-4 w-4" /> Stop
        </Button>
      </div>
    </div>
  );
});

AudioInteraction.displayName = 'AudioInteraction';
export default AudioInteraction;

"use client"

/**
 * @author: @lyui
 * @description: Particle Animation component for creating animated particle systems with configurable circular patterns and dispersion effects
 * @version: 1.0.0
 * @date: 2024-12-19
 * @license: MIT
 * @website: https://ly-ui.dev
 */
import React, { useState, useEffect, useRef, useImperativeHandle, forwardRef } from 'react';

// Interface to define particle properties
interface Particle {
  id: number;
  angle: number;
  radius: number;
  startRadius: number; // Rayon initial pour l'animation de dispersion
  speed: number;
  radiusSpeed: number;
  baseRadius: number;
  radiusAmplitude: number;
  opacity: number;
  size: number;
  isBright: boolean;
  pulsePhase: number;
  pulseSpeed: number;
  transitionProgress: number; // Progress of dispersion animation (0 to 1)
  isInitialAnimation: boolean; // Indicates if it's the initial animation (dispersion)
}

// Interface pour les props du composant
interface ParticleAnimationProps {
  width?: number;
  height?: number;
  numParticles?: number;
  minRadius?: number;
  maxRadius?: number;
  backgroundColor?: string;
  particleColor?: string;
  brightParticleColor?: string;
  showCenter?: boolean;
  showBorders?: boolean;
  className?: string;
}

// Interface for functions exposed via ref
export interface ParticleAnimationHandle {
  startAnimation: () => void;
  pauseAnimation: () => void;
  resumeAnimation: () => void;
  stopAnimation: () => void;
}

// Fonction d'interpolation easeOutQuad pour une transition fluide
const easeOutQuad = (t: number): number => 1 - (1 - t) * (1 - t);

// Reusable particle animation component
const ParticleAnimation = forwardRef<ParticleAnimationHandle, ParticleAnimationProps>(
  (
    {
      width = 300,
      height = 300,
      numParticles = 120,
      minRadius = 80,
      maxRadius = 140,
      backgroundColor = 'transparent',
      particleColor = '#9CA3AF',
      brightParticleColor = '#FFFFFF',
      showCenter = false,
      showBorders = false,
      className = '',
    },
    ref
  ) => {
    const particlesRef = useRef<Particle[]>([]);
    const animationRef = useRef<number | null>(null);
    const [isRunning, setIsRunning] = useState<boolean>(false);
    const [, setRender] = useState<object>({});

    const baseRadius: number = (minRadius + maxRadius) / 2;

    // Fonction pour initialiser les particules
    const initializeParticles = () => {
      particlesRef.current = Array.from({ length: numParticles }, (_, i) => {
        const angle: number = (i / numParticles) * 2 * Math.PI;
        const radiusVariation: number = Math.random() * (maxRadius - minRadius) + minRadius;

        return {
          id: i,
          angle,
          radius: 0, // Particles start at center
          startRadius: 0, // Initial radius for animation
          speed: 0.008 + Math.random() * 0.015,
          radiusSpeed: 0.0008 + Math.random() * 0.0015,
          baseRadius: radiusVariation,
          radiusAmplitude: 25 + Math.random() * 35,
          opacity: 0.4 + Math.random() * 0.6,
          size: 1.5 + Math.random() * 2.5,
          isBright: Math.random() < 0.12,
          pulsePhase: Math.random() * Math.PI * 2,
          pulseSpeed: 0.02 + Math.random() * 0.03,
          transitionProgress: 0, // Progression initiale de l'animation de dispersion --------------------
          isInitialAnimation: true, // Activer la dispersion pour les nouvelles particules
        };
      });

      setRender({});
    };

    // Function to reset initial animation on existing particles
    const resetToInitialAnimation = () => {
      particlesRef.current.forEach((particle: Particle) => {
        particle.radius = 0; // Remettre au centre
        particle.startRadius = 0;
        particle.transitionProgress = 0;
        particle.isInitialAnimation = true; // Reactivate dispersion animation
      });
      setRender({});
    };

    // Initialiser les particules au montage
    useEffect(() => {
      initializeParticles();
    }, [numParticles, minRadius, maxRadius]);

    // Animation loop
    useEffect(() => {
      const animate = (currentTime: number) => {
        if (!isRunning) return;

        const elapsedTime: number = currentTime * 0.001;

        particlesRef.current.forEach((particle: Particle) => {
          // Animation de dispersion (uniquement pour l'animation initiale)
          if (particle.isInitialAnimation && particle.transitionProgress < 1) {
            particle.transitionProgress = Math.min(particle.transitionProgress + 0.016 / 0.5, 1); // 0.5s duration
            const easedProgress = easeOutQuad(particle.transitionProgress);
            particle.radius = particle.startRadius + (particle.baseRadius - particle.startRadius) * easedProgress;
            if (particle.transitionProgress >= 1) {
              particle.isInitialAnimation = false; // Disable dispersion after completion
            }
          } else {
            // Animation normale (rotation et oscillation)
            particle.angle += particle.speed;
            const radiusOscillation: number = Math.sin(elapsedTime * particle.radiusSpeed) * particle.radiusAmplitude;
            particle.radius = particle.baseRadius + radiusOscillation;
            particle.radius = Math.max(minRadius, Math.min(maxRadius, particle.radius));
          }
          particle.pulsePhase += particle.pulseSpeed;
        });

        setRender({});
        animationRef.current = requestAnimationFrame(animate);
      };

      if (isRunning) {
        animationRef.current = requestAnimationFrame(animate);
      }

      return () => {
        if (animationRef.current !== null) {
          cancelAnimationFrame(animationRef.current);
          animationRef.current = null;
        }
      };
    }, [isRunning, minRadius, maxRadius]);

    // Animation control functions
    const startAnimation = () => {
      if (particlesRef.current.length === 0) {
        initializeParticles(); // Create new particles with dispersion
      } else {
        resetToInitialAnimation(); // Reset initial animation on existing particles
      }
      setIsRunning(true);
    };

    const pauseAnimation = () => {
      setIsRunning(false);
      if (animationRef.current !== null) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
    };

    const resumeAnimation = () => {
      setIsRunning(true);
    };

    const stopAnimation = () => {
      setIsRunning(false);
      if (animationRef.current !== null) {
        cancelAnimationFrame(animationRef.current);
        animationRef.current = null;
      }
      particlesRef.current = []; // Reset particles
      setRender({});
    };

    // Expose control functions via ref
    useImperativeHandle(ref, () => ({
      startAnimation,
      pauseAnimation,
      resumeAnimation,
      stopAnimation,
    }));

    return (
      <div
        className={`relative flex items-center justify-center ${className}`}
        style={{
          width: `${width}px`,
          height: `${height}px`,
          backgroundColor,
        }}
      >
        {/* Cercles de référence optionnels */}
        {showBorders && (
          <>
            <div
              className="absolute border border-gray-700 rounded-full opacity-10"
              style={{
                width: `${minRadius * 2}px`,
                height: `${minRadius * 2}px`,
                transform: 'translate(-50%, -50%)',
              }}
            />
            <div
              className="absolute border border-gray-600 rounded-full opacity-15"
              style={{
                width: `${maxRadius * 2}px`,
                height: `${maxRadius * 2}px`,
                transform: 'translate(-50%, -50%)',
              }}
            />
          </>
        )}

        {particlesRef.current.map((particle: Particle) => {
          const x: number = Math.cos(particle.angle) * particle.radius;
          const y: number = Math.sin(particle.angle) * particle.radius;
          const pulseScale: number = 1 + Math.sin(particle.pulsePhase) * 0.3;
          const pulseOpacity: number = particle.opacity + Math.sin(particle.pulsePhase) * 0.25;

          return (
            <div
              key={particle.id}
              className="absolute rounded-full"
              style={{
                left: `calc(50% + ${x}px)`,
                top: `calc(50% + ${y}px)`,
                width: `${particle.size * pulseScale}px`,
                height: `${particle.size * pulseScale}px`,
                backgroundColor: particle.isBright ? brightParticleColor : particleColor,
                opacity: Math.max(0.2, Math.min(1, pulseOpacity)),
                transform: 'translate(-50%, -50%)',
                boxShadow: particle.isBright
                  ? `0 0 ${4 * pulseScale}px ${brightParticleColor}80`
                  : 'none',
              }}
            />
          );
        })}

        {showCenter && (
          <div
            className="absolute w-1 h-1 rounded-full opacity-30"
            style={{
              backgroundColor: particleColor,
              transform: 'translate(-50%, -50%)',
            }}
          />
        )}
      </div>
    );
  }
);

ParticleAnimation.displayName = 'ParticleAnimation';

export default ParticleAnimation;

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const globalVariants = {
   variant: {
      default: "border bg-neutral-200/40 dark:bg-neutral-200/20 dark:hover:bg-neutral-200/40 text-black  dark:border-neutral-200/20  border-neutral-300/50 dark:text-neutral-200",
      ghost: "dark:hover:bg-neutral-700/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40 bg-neutral-200/40 hover:bg-neutral-300/60 dark:bg-neutral-700 dark:text-gray-200",
      outline: "border border-neutral-300/40 dark:hover:bg-neutral-500/40 hover:bg-gray-200/40  dark:text-gray-200",
      none:"bg-none border-none",
    },
}

"use client"
import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn, globalVariants } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center  gap-2 whitespace-nowrap rounded-lg text-sm font-medium ring-offset-white transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-neutral-950 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 dark:ring-offset-neutral-950 dark:focus-visible:ring-neutral-300 cursor-pointer",
  {
    variants: {
      variant: {
        link: "text-neutral-900 underline-offset-4 hover:underline dark:text-neutral-50",
        ...globalVariants.variant,
      },
      size: {
        default: "h-9 px-2.5 rounded-lg  py-0.5",
        sm: "h-9 rounded-lg px-3",
        lg: "h-11 rounded-lg px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };
